export function Comms() {
  const { s, d, toast, nav } = useStore();
  const tab = (s.route.param ?? "whatsapp") as "whatsapp" | "calls" | "emails";
  const [sel, setSel] = useState<string | null>(s.threads[0]?.leadId ?? null);
  const thread = s.threads.find((t) => t.leadId === sel); const lead = s.leads.find((l) => l.id === sel);
  return <div className="anim-up"><PageHeader title="Communications" kicker="WhatsApp · Calls · Email" right={<Seg options={[{ v: "whatsapp", label: "WhatsApp" }, { v: "calls", label: "Calls" }, { v: "emails", label: "Emails" }]} value={tab} onChange={(v) => nav("comms", v)} />} />
    {tab === "whatsapp" && <div className="card grid overflow-hidden lg:grid-cols-[300px_1fr]" style={{ minHeight: 520 }}><div className="overflow-y-auto border-b border-line lg:border-b-0 lg:border-r"><p className="lbl border-b border-line px-3.5 py-2.5">Conversations</p>{s.threads.map((t) => { const l = s.leads.find((x) => x.id === t.leadId); return <button key={t.leadId} onClick={() => setSel(t.leadId)} className={cx("flex w-full items-center gap-2.5 border-b border-line/70 px-3.5 py-3 text-left", sel === t.leadId ? "bg-mint/70" : "hover:bg-mint/40")}><Avatar name={l?.name ?? "?"} hue={((l?.name.length ?? 5) * 37) % 360} size={36} /><div className="min-w-0 flex-1"><p className="truncate text-[12.5px] font-bold">{l?.name}</p><p className="truncate text-[11px] text-slate">{t.messages[t.messages.length - 1]?.text}</p></div></button>; })}</div>{lead ? <div className="flex h-[520px] flex-col"><div className="flex items-center gap-2.5 border-b border-line px-4 py-2.5"><Avatar name={lead.name} hue={(lead.name.length * 37) % 360} size={30} /><div className="min-w-0 flex-1"><button onClick={() => nav("lead", lead.id)} className="text-[13px] font-bold hover:text-fern">{lead.name}</button><p className="num text-[10.5px] text-slate">{lead.phone}</p></div><Badge tone="ok" className="text-[10px]">Cloud API ✓</Badge></div><div className="flex-1 space-y-2 overflow-y-auto bg-mint/25 p-4">{(thread?.messages ?? []).map((m, i) => <div key={i} className={cx("anim-tick max-w-[75%] rounded-xl px-3 py-2 text-[12.5px] leading-relaxed shadow-sm", m.from === "us" ? "ml-auto rounded-br-sm bg-fern text-white" : "rounded-bl-sm border border-line bg-card")}>{m.text}</div>)}</div></div> : <EmptyState icon="bubble" title="Select a conversation" />}</div>}
    {tab === "calls" && <div className="card overflow-x-auto"><table className="w-full min-w-[760px] text-[12.5px]"><thead><tr className="border-b border-line"><th className="th">Contact</th><th className="th">Direction</th><th className="th">Duration</th><th className="th">Outcome</th><th className="th">When</th></tr></thead><tbody>{s.calls.map((c) => <tr key={c.id} className="transition-colors hover:bg-mint/40"><td className="td"><p className="font-bold">{c.name}</p><p className="num text-[10.5px] text-slate2">{c.number}</p></td><td className="td"><Badge tone={c.direction === "Inbound" ? "info" : "neutral"}>{c.direction}</Badge></td><td className="td num">{c.duration > 0 ? `${Math.floor(c.duration / 60)}m ${c.duration % 60}s` : "Missed"}</td><td className="td text-slate">{c.outcome}</td><td className="td num text-[11px] text-slate">{rel(c.at)}</td></tr>)}</tbody></table></div>}
    {tab === "emails" && <div className="card divide-y divide-line">{s.emails.map((e) => <div key={e.id} className="flex flex-wrap items-center gap-3 px-4 py-3 hover:bg-mint/40"><I n="mail" size={16} className="shrink-0 text-moss" /><div className="min-w-0 flex-1"><p className="text-[13px] font-bold">{e.subject}</p><p className="truncate text-[11.5px] text-slate">{e.from} · {e.email}</p></div><Badge tone="neutral" className="text-[10px]">{e.source}</Badge><span className="num text-[10.5px] text-slate2">{rel(e.at)}</span></div>)}</div>}
  </div>;
}

// ============ MARKETING ============
export function Marketing() {
  const { s } = useStore();
  const tab = (s.route.param ?? "campaigns") as "campaigns" | "landing";
  const totalBudget = s.campaigns.reduce((a, c) => a + c.budget, 0); const totalSpent = s.campaigns.reduce((a, c) => a + c.spent, 0);
  return <div className="anim-up"><PageHeader title="Marketing" kicker="Campaigns · Landing pages · ROI" right={<Seg options={[{ v: "campaigns", label: "Campaigns" }, { v: "landing", label: "Landing Pages" }]} value={tab} onChange={(v) => s.route.page === "marketing" && (window.location.hash = v)} />} />
    {tab === "campaigns" && <><div className="mb-4 grid grid-cols-2 gap-3 lg:grid-cols-4">{[{ l: "Campaigns", v: s.campaigns.length }, { l: "Budget", v: aed(totalBudget, true) }, { l: "Spent", v: aed(totalSpent, true) }, { l: "Blended CPL", v: aed(totalSpent / Math.max(1, s.leads.length)) }].map((k) => <div key={k.l} className="card p-4"><p className="lbl">{k.l}</p><p className="num mt-1 text-[24px] font-bold">{k.v}</p></div>)}</div><div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{s.campaigns.map((c) => <div key={c.id} className="card p-4 transition-all hover:-translate-y-0.5 hover:shadow-[var(--shadow-pop)]"><p className="text-[13.5px] font-bold leading-tight">{c.name}</p><p className="num text-[10.5px] text-slate2">{c.platform} · {c.area}</p><div className="mt-3"><div className="mb-1 flex justify-between text-[10.5px] font-bold"><span className="text-slate">Budget use</span><span className="num">{aed(c.spent, true)} / {aed(c.budget, true)}</span></div><div className="h-2 overflow-hidden rounded-full bg-mint"><div className={cx("bar-grow h-full rounded-full", (c.spent / c.budget) > 0.9 ? "bg-warn" : "bg-fern")} style={{ width: `${Math.round((c.spent / c.budget) * 100)}%` }} /></div></div></div>)}</div></>}
    {tab === "landing" && <div className="card overflow-x-auto"><table className="w-full min-w-[820px] text-[12.5px]"><thead><tr className="border-b border-line"><th className="th">Page</th><th className="th">URL</th><th className="th">Source</th><th className="th text-right">Leads</th><th className="th text-right">Conversions</th><th className="th">Status</th><th className="th">Last lead</th></tr></thead><tbody>{s.landingPages.map((lp) => <tr key={lp.id} className="transition-colors hover:bg-mint/40"><td className="td font-bold">{lp.name}</td><td className="td num text-[11px] text-slate">{lp.url}</td><td className="td"><SourceChip source={lp.source} /></td><td className="td num text-right font-bold">{lp.leads}</td><td className="td num text-right font-bold text-fern">{lp.conversions}</td><td className="td"><Badge tone={lp.status === "Live" ? "ok" : lp.status === "Paused" ? "warn" : "neutral"}>{lp.status}</Badge></td><td className="td num text-[11px] text-slate">{rel(lp.lastLead)}</td></tr>)}</tbody></table></div>}
  </div>;
}

// ============ REPORTS ============
export function Reports() {
  const { s } = useStore();
  const stats = useMemo(() => { const qualifiedStages = ["qualified", "requirement", "property_sent", "viewing_req", "viewing_sched", "viewing_done", "offer", "negotiation", "booking", "contract", "payment", "won"]; const viewingStages = ["viewing_req", "viewing_sched", "viewing_done", "offer", "negotiation", "booking", "contract", "payment", "won"]; const map = new Map<string, { leads: number; qualified: number; viewings: number; deals: number; revenue: number; spend: number }>(); for (const l of s.leads) { const src = l.touches[0]?.source ?? "—"; const row = map.get(src) ?? { leads: 0, qualified: 0, viewings: 0, deals: 0, revenue: 0, spend: 0 }; row.leads += 1; if (qualifiedStages.includes(l.stage)) row.qualified += 1; if (viewingStages.includes(l.stage)) row.viewings += 1; if (l.stage === "won") { row.deals += 1; row.revenue += s.deals.filter((d) => d.leadId === l.id).reduce((a, d) => a + d.commission, 0); } map.set(src, row); } for (const c of s.campaigns) { const row = map.get(c.source) ?? { leads: 0, qualified: 0, viewings: 0, deals: 0, revenue: 0, spend: 0 }; row.spend += c.spent; map.set(c.source, row); } return [...map.entries()].map(([source, r]) => ({ source, ...r })).sort((a, b) => b.leads - a.leads); }, [s.leads, s.deals, s.campaigns]);
  return <div className="anim-up"><PageHeader title="Source ROI & Reports" kicker="Which source actually makes money?" />
    <div className="card overflow-x-auto"><table className="w-full min-w-[820px] text-[12.5px]"><thead><tr className="border-b border-line"><th className="th">Source</th><th className="th text-right">Leads</th><th className="th text-right">Qualified</th><th className="th text-right">Viewings</th><th className="th text-right">Deals</th><th className="th text-right">Revenue</th><th className="th text-right">Spend</th><th className="th text-right">ROI</th></tr></thead><tbody>{stats.map((r) => { const roi = r.spend > 0 ? r.revenue / r.spend : null; return <tr key={r.source} className="transition-colors hover:bg-mint/40"><td className="td"><div className="flex items-center gap-2"><span className="h-2.5 w-2.5 rounded-sm" style={{ background: SOURCES[r.source]?.color ?? "#999" }} /><span className="font-bold">{r.source}</span></div></td><td className="td num text-right font-bold">{r.leads}</td><td className="td num text-right">{r.qualified}</td><td className="td num text-right">{r.viewings}</td><td className="td num text-right">{r.deals}</td><td className="td num text-right font-bold text-gold2">{r.revenue ? aed(r.revenue, true) : "—"}</td><td className="td num text-right text-slate">{r.spend ? aed(r.spend, true) : "—"}</td><td className="td num text-right"><Badge tone={roi === null ? "neutral" : roi >= 2 ? "ok" : roi >= 1 ? "gold" : "danger"}>{roi === null ? "n/a" : `${roi.toFixed(1)}×`}</Badge></td></tr>; })}</tbody></table></div></div>;
}

// ============ TEAM ============
export function Team() {
  const { s, d, toast } = useStore();
  const stats = s.users.map((u) => { const leads = s.leads.filter((l) => l.assignedTo === u.id); const contacted = leads.filter((l) => l.firstContactMin !== null); const deals = s.deals.filter((x) => x.agentId === u.id); return { u, leads: leads.length, avg: contacted.length ? Math.round(contacted.reduce((a, l) => a + (l.firstContactMin ?? 0), 0) / contacted.length) : null, comm: deals.reduce((a, x) => a + x.agentShare, 0), deals: deals.length, conv: leads.length ? Math.round((leads.filter((l) => l.stage === "won").length / leads.length) * 100) : 0 }; });
  return <div className="anim-up"><PageHeader title="Team" kicker="Roles · availability · speed · conversion" />
    <div className="grid gap-3 md:grid-cols-2 xl:grid-cols-3">{stats.map(({ u, leads, avg, comm, deals, conv }) => <div key={u.id} className={cx("card p-4 transition-all hover:-translate-y-0.5 hover:shadow-[var(--shadow-pop)]", !u.available && "opacity-70")}><div className="flex items-start gap-3"><Avatar name={u.name} hue={u.hue} size={44} /><div className="min-w-0 flex-1"><p className="truncate text-[14.5px] font-bold">{u.name}</p><p className="text-[10.5px] font-bold uppercase tracking-wide text-gold2">{u.role}</p></div><div className="flex flex-col items-end gap-1"><Toggle on={u.available} onChange={() => { d({ t: "toggleAvail", id: u.id }); toast("info", `${u.name} is now ${u.available ? "OFFLINE" : "ONLINE"}.`); }} /><span className={cx("text-[9.5px] font-bold uppercase", u.available ? "text-ok" : "text-slate2")}>{u.available ? "Online" : "Offline"}</span></div></div><div className="mt-3 grid grid-cols-4 gap-1.5 text-center">{[["Leads", leads], ["Deals", deals], ["Conv", `${conv}%`], ["Comm", aed(comm, true)]].map(([k, v]) => <div key={k as string} className="rounded-lg bg-mint/60 py-1.5"><p className="num text-[15px] font-bold leading-none">{v}</p><p className="lbl mt-0.5 text-[8.5px]">{k}</p></div>)}</div></div>)}</div></div>;
}

