export function Integrations() {
  const { s, d, toast } = useStore();
  const failed = s.webhooks.filter((w) => w.status !== "Processed");
  return <div className="anim-up"><PageHeader title="Integrations" kicker="Adapter → Normalizer → Duplicate Engine → CRM" />
    <div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-3">{s.integrations.map((it) => <div key={it.id} className={cx("card p-4 transition-all hover:-translate-y-0.5 hover:shadow-[var(--shadow-pop)]", it.status === "Error" && "border-danger/40")}><div className="flex items-start gap-3"><div className={cx("flex h-10 w-10 shrink-0 items-center justify-center rounded-lg", it.status === "Connected" ? "bg-fern/10 text-fern" : it.status === "Error" ? "bg-dangersoft text-danger" : "bg-mint text-slate2")}><I n="plug" size={18} /></div><div className="min-w-0 flex-1"><p className="truncate text-[14px] font-bold">{it.name}</p><p className="text-[10px] font-bold uppercase tracking-wide text-slate2">{it.category}</p></div><Badge tone={it.status === "Connected" ? "ok" : it.status === "Error" ? "danger" : "neutral"}>{it.status}</Badge></div><p className="mt-2.5 text-[11.5px] leading-snug text-slate">{it.desc}</p><div className="mt-3 flex items-center gap-2 border-t border-line pt-3"><Toggle on={it.status !== "Off"} onChange={() => { d({ t: "toggleIntegration", id: it.id }); toast(it.status === "Connected" ? "warn" : "success", `${it.name} ${it.status === "Connected" ? "disconnected" : "connected"}.`); }} /><button className="btn btn-ghost !py-1 ml-auto text-[11.5px]" onClick={() => toast("info", `${it.name} configuration.`)}><I n="gear" size={12} /> Configure</button></div></div>)}</div>
    <div className="mt-5 grid gap-4 lg:grid-cols-3"><div className="card p-4 lg:col-span-2"><h3 className="mb-3 flex items-center gap-2 font-display text-[15px] font-bold"><I n="radar" size={15} className="text-gold2" /> Webhook log</h3><table className="w-full text-[12px]"><thead><tr className="border-b border-line"><th className="th">Source</th><th className="th">Event</th><th className="th">Detail</th><th className="th">Status</th></tr></thead><tbody>{s.webhooks.slice(0, 10).map((w) => <tr key={w.id} className="transition-colors hover:bg-mint/40"><td className="td font-bold">{w.source}</td><td className="td num text-[11px]">{w.event}</td><td className="td max-w-[200px] truncate text-slate">{w.detail}</td><td className="td"><Badge tone={w.status === "Processed" ? "ok" : w.status === "Failed" ? "danger" : "warn"}>{w.status}</Badge></td></tr>)}</tbody></table></div><div className="card border-danger/25 p-4"><h3 className="mb-1 flex items-center gap-2 font-display text-[15px] font-bold text-danger"><I n="warning" size={15} /> Failed events queue</h3>{failed.length === 0 && <p className="rounded-lg bg-oksoft px-3 py-2.5 text-[12px] font-bold text-ok">Queue empty ✓</p>}{failed.map((w) => <div key={w.id} className="mb-2 rounded-lg border border-danger/25 bg-dangersoft/40 p-3"><p className="text-[12px] font-bold">{w.source} · {w.event}</p>{w.error && <p className="num mt-1 rounded bg-card px-2 py-1 text-[10px] text-danger">{w.error}</p>}<button className="btn btn-ghost !py-1 mt-2 text-[11px]" onClick={() => { d({ t: "webhookRetry", id: w.id }); toast("success", "Reprocessed."); }}><I n="refresh" size={11} /> Retry</button></div>)}</div></div></div>;
}

